bash -c '
set -e

# 1. Verify Punisher role implementation exists and is Neutral
grep -q "public sealed class Punisher" ExtremeRoles/Roles/Solo/Neutral/Punisher.cs || { echo "FAIL: Punisher class missing"; exit 1; }
grep -q "RoleArgs.BuildNeutral" ExtremeRoles/Roles/Solo/Neutral/Punisher.cs || { echo "FAIL: Not a Neutral role"; exit 1; }

# 2. Verify task-unlocked kill capability & cooldown modifiers
grep -q "requiredTaskNum" ExtremeRoles/Roles/Solo/Neutral/Punisher.cs || { echo "FAIL: Task unlock logic missing"; exit 1; }
grep -q "taskKillCoolReduce" ExtremeRoles/Roles/Solo/Neutral/Punisher.cs || grep -q "nonImpostorKillCoolIncrease" ExtremeRoles/Roles/Solo/Neutral/Punisher.cs || { echo "FAIL: Cooldown modifiers missing"; exit 1; }

# 3. Verify custom options
grep -q "CreateSpecificOption" ExtremeRoles/Roles/Solo/Neutral/Punisher.cs || { echo "FAIL: Custom options missing"; exit 1; }

# 4. Verify registration & win conditions in manager
grep -q "ExtremeRoleId.Punisher" ExtremeRoles/Roles/ExtremeRoleManager.cs || { echo "FAIL: ID missing in manager"; exit 1; }
grep -q "new Punisher()" ExtremeRoles/Roles/ExtremeRoleManager.cs || { echo "FAIL: Instantiation missing"; exit 1; }
grep -q "PunisherKilledImpostor" ExtremeRoles/Roles/ExtremeRoleManager.cs || { echo "FAIL: Win reason enum missing"; exit 1; }

# 5. Verify win checker handles Punisher
grep -q "Punisher.*PunisherKilledImpostor" ExtremeRoles/Module/GameEnd/NeutralSpecialWinChecker.cs || { echo "FAIL: Win checker missing"; exit 1; }

# 6. Verify localization across all required languages
for lang in "" ".en-US" ".fr-FR" ".zh-Hans" ".zh-Hant"; do
  f="ExtremeRoles/Translation/resx/Neutral${lang}.resx"
  [ -f "$f" ] || { echo "FAIL: $f missing"; exit 1; }
  grep -q "Punisher" "$f" || { echo "FAIL: Translation missing in $f"; exit 1; }
done

# 7. Verify unit tests exist
[ -f "ExtremeRoles.UnitTest/Roles/Solo/Neutral/PunisherTests.cs" ] || { echo "FAIL: PunisherTests.cs missing"; exit 1; }

echo "PASS: All acceptance checks for PR #1067 passed."
'

